import "server-only";

import { readFileSync } from "node:fs";
import path from "node:path";

/**
 * Entity names and kinds from the pipeline's crosswalk (pipeline/geo/entities.csv, built from Natural Earth, public
 * domain, and the World Bank CCKP's names of its states and provinces), copied into .generated by scripts/sync-data.mjs.
 * Unknown codes throw: a name is never guessed.
 */
type Entity = { iso3: string; name: string; kind: string; memberOf: string };

let cache: Map<string, Entity> | null = null;

function parseCsvLine(line: string): string[] {
  const out: string[] = [];
  let cur = "";
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quoted) {
      if (ch === '"' && line[i + 1] === '"') {
        cur += '"';
        i++;
      } else if (ch === '"') quoted = false;
      else cur += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ",") {
      out.push(cur);
      cur = "";
    } else cur += ch;
  }
  out.push(cur);
  return out;
}

function table(): Map<string, Entity> {
  if (cache) return cache;
  const text = readFileSync(path.join(process.cwd(), ".generated", "v1", "entities.csv"), "utf8");
  const [header, ...rows] = text.trim().split("\n");
  const cols = parseCsvLine(header);
  const [iC, nC, kC, mC] = ["iso3", "name", "kind", "member_of"].map((c) => cols.indexOf(c));
  if (iC < 0 || nC < 0 || kC < 0 || mC < 0) throw new Error("entities.csv: missing iso3, name, kind or member_of column");
  cache = new Map(
    rows.map((r) => {
      const v = parseCsvLine(r);
      return [v[iC], { iso3: v[iC], name: v[nC], kind: v[kC], memberOf: v[mC] }];
    }),
  );
  return cache;
}

function entity(code: string): Entity {
  const e = table().get(code);
  if (!e) throw new Error(`Unknown entity ${code}: not in pipeline/geo/entities.csv`);
  return e;
}

export function entityName(code: string): string {
  return entity(code).name;
}

/** The crosswalk's kind: country, territory, region (a state or province), aggregate, station and so on. */
export function entityKind(code: string): string {
  return entity(code).kind;
}

/** The country or territory a state or province belongs to (entities.csv member_of). */
export function countryOf(code: string): string {
  const e = entity(code);
  if (e.kind !== "region" || !e.memberOf) throw new Error(`${code} is not a region of a country`);
  return e.memberOf;
}

/** A country or territory (not an aggregate, station or producer pseudo-entity). */
export function isPlace(code: string): boolean {
  const e = entity(code);
  return e.kind === "country" || e.kind === "territory";
}
